export const protectedProcedure = publicProcedure.use(({ next, context }) => {
  if (!context.session?.user) {
    throw new ORPCError('UNAUTHORIZED', {
      message: 'Authentication required',
    });
  }
  return next({ context });
});

const createProjectInput = z.object({
  name: z.string().min(1, 'name required').max(100),
  path: z.string().min(1).refine((p) => p.startsWith('/') || /^[A-Za-z]:/.test(p), { message: 'absolute path required' }),
  settings: SettingsSchema.optional(),
});

export const projectRouter = {
  list: protectedProcedure.handler(async () => projectRepository.findAll()),

  get: protectedProcedure
    .input(z.object({ id: ProjectIdSchema }))
    .handler(async ({ input }) => {
      const project = await projectRepository.findById(input.id);
      if (!project) throw new ORPCError('NOT_FOUND', { message: `Project not found: ${input.id}` });
      return project;
    }),

  create: protectedProcedure
    .input(createProjectInput)
    .handler(async ({ input }) => {
      try {
        return await projectRepository.create({
          id: crypto.randomUUID(),
          name: input.name,
          path: input.path,
          settings: input.settings as Record<string, unknown> | undefined,
        });
      } catch (error) {
        throw new ORPCError('BAD_REQUEST', {
          message: error instanceof Error ? error.message : 'Failed to create project',
        });
      }
    }),

  update: protectedProcedure
    .input(z.object({ id: ProjectIdSchema, data: UpdateProjectInput }))
    .handler(async ({ input }) => {
      try {
        const updateData: Record<string, unknown> = {};
        if (input.data.name !== undefined) updateData.name = input.data.name;
        if (input.data.path !== undefined) updateData.path = input.data.path;
        if (input.data.settings !== undefined) updateData.settings = input.data.settings;
        return await projectRepository.update(input.id, updateData);
      } catch (error) {
        if (error instanceof Error && error.message.includes('not found')) {
          throw new ORPCError('NOT_FOUND', { message: error.message });
        }
        throw new ORPCError('BAD_REQUEST', {
          message: error instanceof Error ? error.message : 'Failed to update project',
        });
      }
    }),

  delete: protectedProcedure
    .input(z.object({ id: ProjectIdSchema }))
    .handler(async ({ input }) => {
      try {
        return await projectRepository.delete(input.id);
      } catch (error) {
        if (error instanceof Error && error.message.includes('not found')) {
          throw new ORPCError('NOT_FOUND', { message: error.message });
        }
        throw new ORPCError('BAD_REQUEST', {
          message: error instanceof Error ? error.message : 'Failed to delete project',
        });
      }
    }),
};
